	if event.SessionRef != "/tmp/gemini.json" {
		t.Errorf("expected session_ref '/tmp/gemini.json', got %q", event.SessionRef)
	}
	if event.Timestamp.IsZero() {
		t.Error("expected non-zero timestamp")
	}
